+static bool are_users_clone_compatible(Node* n, Node* m) {
+  for (DUIterator_Fast imax, i = m->fast_outs(imax); i < imax; i++) {
+    Node* use = m->fast_out(i);
+    if (use == n) {
+      continue;
+    }
+    if (!is_vector_bitwise_not_pattern(use, m) &&
+        !is_valid_sve_arith_imm_pattern(use, m)) {
+      return false;
+    }
+  }
+  return true;
+}
